'use strict';
const fs = require('fs');
const path = require('path');
const os = require('os');
const { execSync } = require('child_process');

const BUS_FILE = path.join(os.homedir(), '.claude', 'memory-bus.json');
const SESSIONS_DIR = path.join(os.homedir(), '.claude', 'sessions');

const MEMORY_PATTERNS = [
  /\/\.claude\/projects\/[^/]+\/memory\/[^/]+\.md$/,
  /\/\.claude\/nisaba\/learning\/[^/]+\.md$/,
];

function getSessionTty() {
  try {
    return execSync('tty', { encoding: 'utf8', stdio: ['pipe', 'pipe', 'ignore'] })
      .trim().replace(/[^a-z0-9]/gi, '_');
  } catch {
    return `ppid_${process.ppid}`;
  }
}

function readBus() {
  try { return JSON.parse(fs.readFileSync(BUS_FILE, 'utf8')); }
  catch { return { sequence: 0, lastWrite: null, writerTty: null, files: [] }; }
}

function writeBus(tty, files) {
  const bus = readBus();
  bus.sequence = (bus.sequence || 0) + 1;
  bus.lastWrite = new Date().toISOString();
  bus.writerTty = tty;
  bus.files = Array.isArray(files) ? files : [files];
  const tmp = `${BUS_FILE}.tmp`;
  fs.mkdirSync(path.dirname(BUS_FILE), { recursive: true });
  fs.writeFileSync(tmp, JSON.stringify(bus, null, 2));
  fs.renameSync(tmp, BUS_FILE);
  return bus;
}

function readSession(tty) {
  try {
    return JSON.parse(fs.readFileSync(path.join(SESSIONS_DIR, `${tty}.json`), 'utf8'));
  } catch {
    const bus = readBus();
    return { tty, startTime: new Date().toISOString(), lastSeenSequence: bus.sequence };
  }
}

function writeSession(tty, data) {
  fs.mkdirSync(SESSIONS_DIR, { recursive: true });
  fs.writeFileSync(path.join(SESSIONS_DIR, `${tty}.json`), JSON.stringify(data, null, 2));
}

function isMemoryFile(filePath) {
  return Boolean(filePath && MEMORY_PATTERNS.some(p => p.test(filePath)));
}

function cleanOldSessions() {
  try {
    const cutoff = Date.now() - 24 * 3600 * 1000;
    for (const f of fs.readdirSync(SESSIONS_DIR)) {
      const full = path.join(SESSIONS_DIR, f);
      if (fs.statSync(full).mtimeMs < cutoff) fs.unlinkSync(full);
    }
  } catch {}
}

module.exports = { getSessionTty, readBus, writeBus, readSession, writeSession, isMemoryFile, cleanOldSessions, BUS_FILE, SESSIONS_DIR };

