#!/usr/bin/env node
// PreToolUse — token economy + cross-terminal memory awareness
'use strict';
const fs = require('fs');
const path = require('path');
const os = require('os');
const bus = require('./memory-bus.js');

const STATE_FILE = '/Users/marcelspatz/NUDIMMUD/.claude/state/token-session.json';
const MEMORY_INDEX = path.join(os.homedir(), '.claude', 'projects', '-Users-marcelspatz-NUDIMMUD', 'memory', 'MEMORY.md');

const HEAVY_TOOLS = new Set(['Agent', 'WebSearch', 'WebFetch', 'TaskCreate']);

try {
    const input = fs.readFileSync(0, 'utf-8').trim();
    if (!input) process.exit(0);
    const event = JSON.parse(input);

    const toolName = event?.tool_name || event?.tool || '';
    const toolInput = JSON.stringify(event?.tool_input || {});

    // ── Cross-terminal memory check ──────────────────────────────────────────
    const tty = bus.getSessionTty();
    const currentBus = bus.readBus();
    const session = bus.readSession(tty);

    if (
      currentBus.sequence > session.lastSeenSequence &&
      currentBus.writerTty &&
      currentBus.writerTty !== tty
    ) {
        // Another terminal wrote memory — inject fresh MEMORY.md
        let memoryContent = '';
        try { memoryContent = fs.readFileSync(MEMORY_INDEX, 'utf8').trim(); } catch (_) {}

        const changedFiles = (currentBus.files || []).join(', ') || 'memory files';
        const additionalContext = [
            `[CROSS-TERMINAL MEMORY UPDATE] Another Claude terminal wrote: ${changedFiles}`,
            `Updated at: ${currentBus.lastWrite}`,
            '',
            'Current memory index:',
            memoryContent || '(could not read MEMORY.md)',
        ].join('\n');

        // Update session so we don't re-notify until next cross-terminal write
        session.lastSeenSequence = currentBus.sequence;
        bus.writeSession(tty, session);

        // Lazy cleanup of stale session files (once per notification)
        bus.cleanOldSessions();

        process.stderr.write(JSON.stringify({
            hookSpecificOutput: {
                hookEventName: 'PreToolUse',
                additionalContext,
            }
        }));
    }

    // ── Token economy check ──────────────────────────────────────────────────
    const isHeavy = HEAVY_TOOLS.has(toolName);
    const score = (isHeavy ? 600 : 100) + Math.floor(toolInput.length / 10);

    let contextPct = 0;
    let sessionTokens = 0;
    try {
        const s = JSON.parse(fs.readFileSync(STATE_FILE, 'utf-8'));
        sessionTokens = s.totalTokens || 0;
        contextPct = s.context || 0;
    } catch (_) {}

    if (contextPct > 75 && isHeavy) {
        process.stderr.write(JSON.stringify({
            hookSpecificOutput: {
                hookEventName: 'PreToolUse',
                additionalContext: `TOKEN_ECONOMY: Context at ${contextPct}% — tool "${toolName}" is expensive (score: ${score}). Consider offloading to @deepseek or @qwen. Session total: ${sessionTokens.toLocaleString()} tokens.`
            }
        }));
    }

    process.exit(0);
} catch (_) {
    process.exit(0);
}

